const flashcards = [
    { front: "你好", back: "Hello" },
    { front: "謝謝", back: "Thank you" },
    { front: "再見", back: "Goodbye" },
    { front: "是", back: "Yes" },
    { front: "不是", back: "No" },
    { front: "蘋果", back: "Apple" },
    { front: "水", back: "Water" },
    { front: "朋友", back: "Friend" },
    { front: "愛", back: "Love" },
    { front: "家", back: "Home" }
];

let currentCardIndex = 0;
let isFlipped = false;
let mode = 'learn'; // 'learn' or 'test'
let score = 0;
let totalAsked = 0;

let timer;
let timeLeft = 30;

const flashcard = document.getElementById('flashcard');
const flashcardFront = document.getElementById('flashcard-front');
const flashcardBack = document.getElementById('flashcard-back');
const flipButton = document.getElementById('flip-button');
const prevButton = document.getElementById('prev-button');
const nextButton = document.getElementById('next-button');
const testModeButton = document.getElementById('test-mode-button');
const testContainer = document.getElementById('test-container');
const testDirection = document.getElementById('test-direction');
const timerDisplay = document.getElementById('timer');
const answerInput = document.getElementById('answer-input');
const submitAnswerButton = document.getElementById('submit-answer-button');
const result = document.getElementById('result');

function updateCardContent() {
    flashcardFront.textContent = flashcards[currentCardIndex].front;
    flashcardBack.textContent = flashcards[currentCardIndex].back;
    if (mode === 'test') {
        const direction = testDirection.value;
        if (direction === 'zh-en') {
            flashcardFront.textContent = flashcards[currentCardIndex].front;
            flashcardBack.textContent = ''; // Hide back in test mode until answer
        } else { // en-zh
            flashcardFront.textContent = flashcards[currentCardIndex].back;
            flashcardBack.textContent = ''; // Hide back in test mode until answer
        }
        answerInput.value = '';
        result.textContent = '';
        submitAnswerButton.disabled = false;
        resetTimer();
        startTimer();
    } else {
        flashcard.classList.remove('flipped');
        isFlipped = false;
    }
}

function flipCard() {
    if (mode === 'learn') {
        flashcard.classList.toggle('flipped');
        isFlipped = !isFlipped;
    }
}

function nextCard() {
    currentCardIndex = (currentCardIndex + 1) % flashcards.length;
    isFlipped = false;
    flashcard.classList.remove('flipped');
    updateCardContent();
}

function previousCard() {
    currentCardIndex = (currentCardIndex - 1 + flashcards.length) % flashcards.length;
    isFlipped = false;
    flashcard.classList.remove('flipped');
    updateCardContent();
}

function toggleTestMode() {
    if (mode === 'learn') {
        mode = 'test';
        document.body.classList.add('test-mode-active');
        testModeButton.textContent = 'Learn Mode';
        flipButton.style.display = 'none';
        testContainer.style.display = 'block';
        flashcard.removeEventListener('click', flipCard);
        score = 0;
        totalAsked = 0;
        result.textContent = `Score: 0/0`;
        flashcard.classList.remove('flipped');
        isFlipped = false;
        updateCardContent();
        resetTimer();
        startTimer();
    } else {
        mode = 'learn';
        document.body.classList.remove('test-mode-active');
        testModeButton.textContent = 'Test Mode';
        flipButton.style.display = 'inline-block';
        testContainer.style.display = 'none';
        flashcard.addEventListener('click', flipCard);
        updateCardContent();
        flashcard.classList.remove('flipped');
        isFlipped = false;
        stopTimer();
    }
}

function checkAnswer() {
    stopTimer();
    submitAnswerButton.disabled = true;
    const userAnswer = answerInput.value.trim().toLowerCase();

    const direction = testDirection.value;
    let correctAnswer;
    let incorrectAnswerMessage;

    if (direction === 'zh-en') {
        correctAnswer = flashcards[currentCardIndex].back.toLowerCase();
        incorrectAnswerMessage = `Incorrect. The answer is "${flashcards[currentCardIndex].back}". Score: ${score}/${totalAsked}`;
    } else { // en-zh
        correctAnswer = flashcards[currentCardIndex].front.toLowerCase();
        incorrectAnswerMessage = `Incorrect. The answer is "${flashcards[currentCardIndex].front}". Score: ${score}/${totalAsked}`;
    }

    if (userAnswer) {
        totalAsked++;
    }

    if (userAnswer === correctAnswer) {
        score++;
        result.textContent = `Correct! Score: ${score}/${totalAsked}`;
        result.style.color = 'green';
    } else {
        result.textContent = incorrectAnswerMessage;
        result.style.color = 'red';
    }

    setTimeout(nextCard, 1500);
}

function startTimer() {
    timer = setInterval(() => {
        timeLeft--;
        timerDisplay.textContent = `00:${timeLeft < 10 ? '0' : ''}${timeLeft}`;
        if (timeLeft <= 0) {
            checkAnswer();
        }
    }, 1000);
}

function stopTimer() {
    clearInterval(timer);
}

function resetTimer() {
    stopTimer();
    timeLeft = 30;
    timerDisplay.textContent = `00:30`;
}


// Event Listeners
flipButton.addEventListener('click', flipCard);
flashcard.addEventListener('click', flipCard);
prevButton.addEventListener('click', previousCard);
nextButton.addEventListener('click', nextCard);
testModeButton.addEventListener('click', toggleTestMode);
submitAnswerButton.addEventListener('click', checkAnswer);
testDirection.addEventListener('change', updateCardContent);

// Initialize the first card
updateCardContent();

