    ],
    "Korean": [
        { front: "你好", back: "안녕하세요" }, { front: "謝謝", back: "감사합니다" }, { front: "再見", back: "안녕히 가세요" },
        { front: "是", back: "네" }, { front: "不是", back: "아니요" }, { front: "蘋果", back: "사과" },
